pub fn unique(values: &[i32]) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();
    for value in values {
        if !seen.insert(*value) {
            result.push(*value);
        }
    }
    result
}

pub fn unique(values: &[i32]) -> Vec<i32> {
    let mut sorted = values.to_vec();
    sorted.sort();
    sorted.dedup();
    sorted
}

